def check(story):
    if not story.startswith("As a "):
        return "missing role"
    if ", I want " not in story:
        return "missing capability"
    if ", so that " not in story:
        return "missing goal"
    return "OK"

cards = [
    "As a nurse, I want today's schedule, so that I plan rounds.",
    "As a user, I want faster search.",
    "I want it modern.",
]
for i, c in enumerate(cards, 1):
    print(i, check(c))

WHY = {
    'SMS reminders': 'fewer missed appointments',
    'fewer missed appointments': 'keep every slot full',
}

def ladder_up(feature):
    chain = [feature]
    while chain[-1] in WHY:
        chain.append(WHY[chain[-1]])
    return ' -> '.join(chain)

print(ladder_up('SMS reminders'))
print(ladder_up('keep every slot full'))

