WHY = {
    'send SMS reminders': 'reduce no-shows',
    'open a waitlist': 'reduce no-shows',
    'reduce no-shows': 'keep every slot full',
}
HOW = {'reduce no-shows': ['send SMS reminders', 'open a waitlist']}

def ladder_up(feature):
    chain = [feature]
    while chain[-1] in WHY:
        chain.append(WHY[chain[-1]])
    return chain

for f in ['send SMS reminders', 'open a waitlist']:
    print(' -> '.join(ladder_up(f)))
print('down: %s' % ', '.join(HOW['reduce no-shows']))
